        int i = 0;

        foreach (GameObject button in Buttons)
        {
            button.GetComponentInChildren<KMSelectable>().OnInteract += delegate ()
            {
                ButtonInteract(button);
                return false;
            };

            buttonsGrid[ExpandTo3D(i, 0), ExpandTo3D(i, 1), ExpandTo3D(i, 2)] = button;
            i++;
        }
