            }
        }
        if (buttonsActivated.Cast<bool>().All(x => x == false))
        {
            int one = Random.Range(0, 27);
            ToggleAdjacentButtons(Buttons[one], ExpandTo3D(one, 0), ExpandTo3D(one, 1), ExpandTo3D(one, 2));
        }

        string[] boardLayout = buttonsActivated.Cast<bool>().Select(x => x ? "1" : "0").ToArray();
