    private void ButtonInteract(GameObject button)
    {
        int index = Array.IndexOf(Buttons, button);
        Play(Sound.ButtonPress);
        StartCoroutine(ButtonAnimation(button.transform, index));
        ToggleAdjacentButtons(button, ExpandTo3D(index, 0), ExpandTo3D(index, 1), ExpandTo3D(index, 2));
    }

    private void ToggleAdjacentButtons(GameObject button, int x, int y, int z)
    {
        string currentCommand = x.ToString() + y.ToString() + z.ToString();
        // Solutions are just an XOR of the original solution and any subsequent moves
        if (!optimalSolution.Contains(currentCommand))
        {
            optimalSolution.Add(currentCommand);
        }
        else
        {
            optimalSolution.Remove(currentCommand);
        }
        // Toggle the selected button
        ToggleButton(button, x, y, z);
        // Toggle buttons on the same row
        if (z - 1 >= 0)
        {
            ToggleButton(buttonsGrid[x, y, z - 1], x, y, z - 1);
        }
        if (z + 1 <= 2)
        {
            ToggleButton(buttonsGrid[x, y, z + 1], x, y, z + 1);
        }
        // Toggle buttons in the same column
        if (y - 1 >= 0)
        {
            ToggleButton(buttonsGrid[x, y - 1, z], x, y - 1, z);
        }
        if (y + 1 <= 2)
        {
            ToggleButton(buttonsGrid[x, y + 1, z], x, y + 1, z);
        }
        // Toggle buttons in the same position on other layers
        if (x - 1 >= 0)
        {
            ToggleButton(buttonsGrid[x - 1, y, z], x - 1, y, z);
        }
        if (x + 1 <= 2)
        {
            ToggleButton(buttonsGrid[x + 1, y, z], x + 1, y, z);
        }
    }

    private void ToggleButton(GameObject button, int x, int y, int z)
    {
        buttonsActivated[x, y, z] = !buttonsActivated[x, y, z];
        button.GetComponent<Renderer>().material = ButtonMaterials[buttonsActivated[x, y, z] ? 1 : 0];
        StartCoroutine(LightAnimation(button.transform.Find("LightQuad").transform, FlattenTo2D(x, y, z), buttonsActivated[x, y, z]));
        if (buttonsActivated.Cast<bool>().All(i => i == false))
        {
            Solve("All lights were turned off. Module solved!");
        }
    }

    private IEnumerator ButtonAnimation(Transform button, int index)
    {
        Vector3 defaultPosition = button.localPosition;
        for (int i = 0; i < 5; i++)
        {
            button.localPosition += (Vector3.down * 0.006f) / 5;
            yield return new WaitForSeconds(0.01f);
        }
        button.localPosition = defaultPosition + (Vector3.down * 0.006f);
        for (int i = 0; i < 5; i++)
        {
            button.localPosition -= Vector3.down * 0.006f / 5;
            yield return new WaitForSeconds(0.01f);
        }
        button.localPosition = defaultPosition;
        
    }

    private IEnumerator LightAnimation(Transform light, int index, bool activated)
    {
        for (int i = 0; i < 15; i++)
        {
            light.localScale += Vector3.one * (activated ? 7 : -7) / 15;
            yield return new WaitForSeconds(0.01f);
        }
        light.localScale = activated ? Vector3.one * 7 : Vector3.zero;
    }

    private int ExpandTo3D(int index, int dimension)
    {
        int i = 0;

        switch (dimension)
        {
            case 0:
                i = index / 9;
                break;
            case 1:
                i = (index / 3) % 3;
                break;
            case 2:
                i = index % 3;
                break;
            default:
                i = -1;
                break;
        }

        return i;
    }

    private int FlattenTo2D(int x, int y, int z)
    {
        return (x * 9) + (y * 3) + z;
    }

