    IEnumerator ProcessTwitchCommand(string command)
    {
        command = command.Trim().ToLower();
        yield return null;
        string[] commands = command.Split(' ');
        for (int i = 0; i < commands.Length; i++)
        {
            if (!Regex.IsMatch(commands[i], @"^[0-2]{3}$"))
            {
                yield return "sendtochaterror Each button press must be separated by spaces and contain exactly three numbers from 0-2.";
                yield break;
            }
        }
        for (int i = 0; i < commands.Length; i++)
        {
            buttonsGrid[int.Parse(commands[i][0].ToString()), int.Parse(commands[i][1].ToString()), int.Parse(commands[i][2].ToString())].GetComponentInChildren<KMSelectable>().OnInteract();
            yield return new WaitForSeconds(.1f);
        }
    }

    IEnumerator TwitchHandleForcedSolve()
